function readLocalList(key) {
  try { const value = JSON.parse(localStorage.getItem(key) || '[]'); return Array.isArray(value) ? [...new Set(value)] : []; }
  catch { return []; }
}
function readLocalObject(key) {
  try { const value = JSON.parse(localStorage.getItem(key) || '{}'); return value && typeof value === 'object' && !Array.isArray(value) ? value : {}; }
  catch { return {}; }
}
let favorites = readLocalList('kaomoji-favorites');
let recents = readLocalList('kaomoji-recents');
let clipboardTray = readLocalList('kaomoji-clipboard-tray');
let usage = readLocalObject('kaomoji-usage');
let collections = readLocalObject('kaomoji-collections');

function save() {
  localStorage.setItem('kaomoji-favorites', JSON.stringify(favorites));
  localStorage.setItem('kaomoji-recents', JSON.stringify(recents));
  localStorage.setItem('kaomoji-clipboard-tray', JSON.stringify(clipboardTray));
  localStorage.setItem('kaomoji-usage', JSON.stringify(usage));
  localStorage.setItem('kaomoji-collections', JSON.stringify(collections));
}

function saveCategoryOrder() {
  localStorage.setItem('kaomoji-category-order', JSON.stringify(categories.map(([key]) => key)));
  resetCategoryOrderButton.hidden = categories.map(([key]) => key).join('|') === defaultCategories.map(([key]) => key).join('|');
}

function reorderCategories(fromKey, toKey, placeAfter = false) {
  if (!fromKey || !toKey || fromKey === toKey) return;
  const from = categories.findIndex(([key]) => key === fromKey);
  let to = categories.findIndex(([key]) => key === toKey);
  const [moved] = categories.splice(from, 1);
  if (from < to) to -= 1;
  categories.splice(to + (placeAfter ? 1 : 0), 0, moved);
  saveCategoryOrder(); renderCategories();
}

reorderCategoriesButton.addEventListener('click', () => {
  categoryReorderMode = !categoryReorderMode;
  reorderCategoriesButton.setAttribute('aria-pressed', String(categoryReorderMode));
  reorderCategoriesButton.textContent = categoryReorderMode ? '完成排序' : '調整順序';
  categoryEl.closest('.category-bar').classList.toggle('reorder-mode', categoryReorderMode);
  renderCategories();
});

window.addEventListener('storage', event => {
  if (event.key === 'kaomoji-favorites') favorites = readLocalList('kaomoji-favorites');
  if (event.key === 'kaomoji-recents') recents = readLocalList('kaomoji-recents');
  if (event.key === 'kaomoji-usage') usage = readLocalObject('kaomoji-usage');
  if (event.key === 'kaomoji-collections') collections = readLocalObject('kaomoji-collections');
  if (['kaomoji-favorites', 'kaomoji-recents', 'kaomoji-usage', 'kaomoji-collections'].includes(event.key)) { renderList(); renderPersonalPanel(); }
});

function matchesCategory(item) {
  if (activeCollection) return (collections[activeCollection] || []).includes(item.text);
  if (activeCategory === 'all' || activeCategory === 'updated') return true;
  if (activeCategory === 'favorites') return favorites.includes(item.text);
  if (activeCategory === 'recent') return recents.includes(item.text);
  if (activeCategory === 'more') return true;
  return item.tags.includes(activeCategory);
}

function makeToolButton(label, handler, className = '') {
  const button = document.createElement('button'); button.type = 'button'; button.textContent = label; button.className = className;
  button.addEventListener('click', handler); return button;
}

function renderPersonalPanel() {
  personalPanel.replaceChildren();
  toolTabs.forEach(button => button.classList.toggle('active', button.dataset.personalView === personalView));
  clipboardCount.textContent = clipboardTray.length;
  if (personalView === 'frequent') {
    const entries = Object.entries(usage).sort(([, a], [, b]) => b - a).slice(0, 8);
    if (!entries.length) { const note = document.createElement('p'); note.textContent = '複製過的顏文字會自動放在這裡。'; personalPanel.append(note); return; }
    entries.forEach(([text, count]) => personalPanel.append(makeToolButton(`${text} · ${count}`, () => copyItem(text))));
  }
  if (personalView === 'collections') {
    personalPanel.append(makeToolButton('＋ 新增資料夾', createCollection, 'primary-tool'));
    const names = Object.keys(collections);
    if (!names.length) { const note = document.createElement('p'); note.textContent = '建立資料夾，整理聊天、遊戲或日常用的顏文字。'; personalPanel.append(note); }
    names.forEach(name => {
      const count = collections[name].length;
      const button = makeToolButton(`${name} · ${count}`, () => {
        activeCollection = activeCollection === name ? '' : name; activeCategory = 'all'; renderList(); renderPersonalPanel();
      }, `collection-chip${activeCollection === name ? ' primary-tool' : ''}`);
      button.title = '點一下篩選；按住不放可刪除';
      button.addEventListener('contextmenu', event => { event.preventDefault(); if (confirm(`刪除「${name}」資料夾？顏文字不會被刪除。`)) { delete collections[name]; if (activeCollection === name) activeCollection = ''; save(); renderPersonalPanel(); renderList(); } });
      personalPanel.append(button);
    });
  }
  if (personalView === 'clipboard') {
    if (!clipboardTray.length) { const note = document.createElement('p'); note.textContent = '點擊顏文字後會暫存在這裡，可一次複製。'; personalPanel.append(note); return; }
    personalPanel.append(makeToolButton('複製全部', () => copyMany(clipboardTray), 'primary-tool'));
    personalPanel.append(makeToolButton('清空', () => { clipboardTray = []; save(); renderPersonalPanel(); }, 'danger-tool'));
    clipboardTray.slice(0, 10).forEach(text => personalPanel.append(makeToolButton(text, () => copyItem(text))));
  }
}

function createCollection() {
  const name = prompt('資料夾名稱（例如：聊天、遊戲、日常）')?.trim();
  if (!name) return;
  if (!collections[name]) collections[name] = [];
  save(); renderPersonalPanel();
}

function addToCollection(text) {
  let names = Object.keys(collections);
  if (!names.length) { createCollection(); names = Object.keys(collections); }
  if (!names.length) return;
  const name = prompt(`輸入資料夾名稱：\n${names.join('、')}`, names[0])?.trim();
  if (!name) return;
  if (!collections[name]) collections[name] = [];
  collections[name] = [text, ...collections[name].filter(item => item !== text)];
  favorites = favorites.includes(text) ? favorites : [text, ...favorites];
  save(); renderPersonalPanel();
}

async function copyMany(items) {
  const value = items.join(' ');
  try { await navigator.clipboard.writeText(value); }
  catch { window.prompt('請複製這組顏文字：', value); }
}

function showDetails(item) {
  detailItem = item; detailKaomoji.textContent = item.text;
  detailName.textContent = `${item.tags.slice(0, 2).join('・')} 顏文字 · 已做跨平台字元校正`;
  detailTags.replaceChildren(); item.tags.forEach(tag => { const chip = document.createElement('span'); chip.textContent = tag; detailTags.append(chip); });
  similarKaomojis.replaceChildren();
  data.filter(other => other.text !== item.text && other.tags.some(tag => item.tags.includes(tag))).slice(0, 6).forEach(other => similarKaomojis.append(makeToolButton(other.text, () => showDetails(other))));
  if (!detailsDialog.open) detailsDialog.showModal();
}

function getSearchTerms(query) {
  const direct = queryAliases[query] || [];
  const reverse = Object.entries(queryAliases).filter(([, values]) => values.includes(query)).map(([key]) => key);
  return [...new Set([query, ...direct, ...reverse])];
}

function getVisibleItems() {
  const query = searchInput.value.trim().toLowerCase();
  let items = data.filter(item => matchesCategory(item));
  if (query) {
    const terms = getSearchTerms(query);
    items = items.map(item => {
      const tags = item.tags.join(' ').toLowerCase();
      const score = terms.reduce((best, term) => Math.max(best, item.text.includes(term) ? 4 : item.tags.includes(term) ? 3 : tags.includes(term) ? 2 : 0), 0);
      return { item, score };
    }).filter(({ score }) => score > 0).sort((a, b) => b.score - a.score).map(({ item }) => item);
  }
  if (activeCategory === 'recent') items.sort((a, b) => recents.indexOf(a.text) - recents.indexOf(b.text));
  if (activeCollection) items.sort((a, b) => (collections[activeCollection] || []).indexOf(a.text) - (collections[activeCollection] || []).indexOf(b.text));
  return items;
}

function renderRelatedSearches() {
  relatedSearchesEl.replaceChildren();
  const query = searchInput.value.trim();
  const suggestions = relatedSearches[query] || (query ? ['可愛', '打招呼', '加油'] : []);
  suggestions.forEach(term => {
    const button = document.createElement('button'); button.type = 'button'; button.textContent = term;
    button.addEventListener('click', () => setSearch(term)); relatedSearchesEl.append(button);
  });
}

function setSearch(value) {
  searchInputs.forEach(input => { input.value = value; });
  clearButton.classList.toggle('visible', Boolean(value)); renderList(); searchInput.focus();
}

function renderCategories() {
  categoryEl.replaceChildren();
  categories.forEach(([key, label]) => {
    const button = document.createElement('button');
    button.type = 'button'; button.className = `category-button${key === activeCategory || (key === 'more' && expandedFilters) ? ' active' : ''}`;
    const text = document.createElement('span'); text.textContent = label;
    const handle = document.createElement('span'); handle.className = 'category-drag-handle'; handle.textContent = '⠿'; handle.setAttribute('aria-hidden', 'true'); handle.draggable = categoryReorderMode;
    button.append(text, handle); button.dataset.category = key; button.draggable = false; button.title = categoryReorderMode ? '拖曳右側把手調整位置' : '點「調整順序」後可拖移';
    button.addEventListener('click', () => {
      if (categoryReorderMode || touchReordering || suppressCategoryClick) return;
      if (key === 'more') { expandedFilters = !expandedFilters; filterPanel.hidden = !expandedFilters; renderCategories(); return; }
      activeCollection = ''; activeCategory = key; expandedFilters = false; filterPanel.hidden = true; renderCategories(); renderFilters(); renderPersonalPanel(); renderList();
    });
    button.addEventListener('dragstart', event => { draggedCategory = key; button.classList.add('dragging'); event.dataTransfer.effectAllowed = 'move'; });
    button.addEventListener('dragend', () => { draggedCategory = null; dragOverCategory = null; dropAfterCategory = false; categoryEl.classList.remove('reorder-mode'); renderCategories(); });
    button.addEventListener('dragover', event => {
      if (!draggedCategory || draggedCategory === key) return;
      event.preventDefault();
      dragOverCategory = key; dropAfterCategory = event.clientX > button.getBoundingClientRect().left + button.offsetWidth / 2;
      categoryEl.querySelectorAll('.drop-target, .drop-target-after').forEach(item => item.classList.remove('drop-target', 'drop-target-after'));
      button.classList.add(dropAfterCategory ? 'drop-target-after' : 'drop-target'); categoryEl.classList.add('reorder-mode');
    });
    button.addEventListener('drop', event => { event.preventDefault(); reorderCategories(draggedCategory, key, dropAfterCategory); });
    button.addEventListener('pointerdown', event => {
      if (event.pointerType !== 'touch' || !categoryReorderMode) return;
      touchTimer = window.setTimeout(() => {
        touchReordering = true; draggedCategory = key; dropAfterCategory = false;
        button.setPointerCapture?.(event.pointerId); categoryEl.classList.add('reorder-mode'); button.classList.add('dragging');
      }, 350);
    });
    handle.addEventListener('pointerdown', event => {
      if (!categoryReorderMode) return;
      window.clearTimeout(touchTimer); touchReordering = true; draggedCategory = key; dropAfterCategory = false;
      handle.setPointerCapture?.(event.pointerId); categoryEl.classList.add('reorder-mode'); button.classList.add('dragging');
      event.preventDefault(); event.stopPropagation();
    });
    button.addEventListener('pointermove', event => {
      if (!touchReordering || !draggedCategory) return;
      event.preventDefault();
      const target = document.elementFromPoint(event.clientX, event.clientY)?.closest('.category-button');
      if (target && target.dataset.category !== draggedCategory) {
        dragOverCategory = target.dataset.category; dropAfterCategory = event.clientX > target.getBoundingClientRect().left + target.offsetWidth / 2;
        categoryEl.querySelectorAll('.drop-target, .drop-target-after').forEach(item => item.classList.remove('drop-target', 'drop-target-after'));
        target.classList.add(dropAfterCategory ? 'drop-target-after' : 'drop-target');
      }
    });
    button.addEventListener('pointerup', () => {
      window.clearTimeout(touchTimer);
      if (touchReordering) {
        suppressCategoryClick = true; reorderCategories(draggedCategory, dragOverCategory, dropAfterCategory);
        touchReordering = false; draggedCategory = null; dragOverCategory = null; dropAfterCategory = false;
        window.setTimeout(() => { suppressCategoryClick = false; }, 80);
      }
    });
    button.addEventListener('pointercancel', () => { window.clearTimeout(touchTimer); touchReordering = false; draggedCategory = null; dragOverCategory = null; dropAfterCategory = false; renderCategories(); });
    categoryEl.append(button);
  });
  saveCategoryOrder();
}

function renderFilters() {
  filterPanel.replaceChildren();
  Object.entries(filterGroups).forEach(([group, tags]) => {
    const wrapper = document.createElement('div'); wrapper.className = 'filter-group';
    const label = document.createElement('span'); label.textContent = group; wrapper.append(label);
    const options = document.createElement('div'); options.className = 'filter-options';
    tags.forEach(tag => {
      const button = document.createElement('button'); button.type = 'button'; button.className = `filter-option${activeCategory === tag ? ' active' : ''}`; button.textContent = tag;
      button.addEventListener('click', () => { activeCollection = ''; activeCategory = tag; expandedFilters = false; filterPanel.hidden = true; renderCategories(); renderFilters(); renderPersonalPanel(); renderList(); });
      options.append(button);
    });
    wrapper.append(options); filterPanel.append(wrapper);
  });
}

function renderList() {
  const items = getVisibleItems();
  listEl.replaceChildren();
  listTitle.textContent = searchInput.value.trim() ? `搜尋「${searchInput.value.trim()}」` : activeCollection ? `收藏資料夾・${activeCollection}` : `${categoryNames[activeCategory] || activeCategory}顏文字`;
  const descriptions = { all: '從今天的心情開始挑選。', updated: '剛加入的顏文字。', recent: '你最近複製過的內容。', favorites: '留給下一次使用。', 動物: '貓、熊與各種可愛生物。', 人物: '日常情緒與表情。', 手勢: '用動作代替一句話。', 愛心: '把喜歡傳出去。', 符號: '特殊符號與裝飾性文字。', 裝飾: '讓訊息多一點氣氛。', more: '用完整分類找到剛剛好的表情。' };
  categoryDescription.textContent = searchInput.value.trim() ? '依名稱、用途、外觀與關鍵字篩選。' : activeCollection ? '你的個人整理，儲存在此裝置。' : descriptions[activeCategory];
  countEl.textContent = `${items.length} 個`;
  emptyEl.hidden = items.length > 0;
  if (!items.length) renderRelatedSearches();
  items.forEach(item => {
    const fragment = template.content.cloneNode(true);
    const row = fragment.querySelector('.kaomoji-row');
    const copy = fragment.querySelector('.kaomoji-copy');
    const text = fragment.querySelector('.kaomoji-text');
    const favorite = fragment.querySelector('.favorite-button');
    const details = fragment.querySelector('.details-button');
    const collection = fragment.querySelector('.collection-button');
    text.textContent = item.text;
    fragment.querySelector('.kaomoji-tags').innerHTML = [...item.tags.slice(0, 2), '跨平台'].map(tag => `<i>${tag}</i>`).join('');
    copy.setAttribute('aria-label', `複製：${item.tags.slice(0, 2).join('、')} ${item.text}`);
    favorite.classList.toggle('active', favorites.includes(item.text));
    favorite.setAttribute('aria-label', favorites.includes(item.text) ? '取消收藏' : '加入收藏');
    copy.addEventListener('click', () => copyItem(item.text, row));
    favorite.addEventListener('click', () => toggleFavorite(item.text));
    details.addEventListener('click', () => showDetails(item));
    collection.addEventListener('click', () => addToCollection(item.text));
    listEl.append(fragment);
  });
}

async function copyItem(text, row) {
  try { await navigator.clipboard.writeText(text); }
  catch { const input = document.createElement('textarea'); input.value = text; document.body.append(input); input.select(); document.execCommand('copy'); input.remove(); }
  recents = [text, ...recents.filter(item => item !== text)].slice(0, 30); save();
  usage[text] = (usage[text] || 0) + 1;
  clipboardTray = [text, ...clipboardTray.filter(item => item !== text)].slice(0, 12);
  save(); renderPersonalPanel();
  if (row) { row.classList.add('copied'); window.setTimeout(() => row.classList.remove('copied'), 800); }
}

function toggleFavorite(text) {
  favorites = favorites.includes(text) ? favorites.filter(item => item !== text) : [text, ...favorites];
  save(); renderList();
}

searchInputs.forEach(input => input.addEventListener('input', event => {
  searchInputs.forEach(other => { if (other !== event.target) other.value = event.target.value; });
  clearButton.classList.toggle('visible', Boolean(searchInput.value));
  renderList();
}));
clearButton.addEventListener('click', () => {
  searchInputs.forEach(input => { input.value = ''; });
  clearButton.classList.remove('visible'); searchInput.focus(); renderList();
});
document.querySelectorAll('.suggestions button:not(#random-button):not(#mood-button)').forEach(button => button.addEventListener('click', () => setSearch(button.textContent)));
document.querySelector('#reset-button').addEventListener('click', () => {
  searchInputs.forEach(input => { input.value = ''; });
  activeCollection = ''; activeCategory = 'all'; clearButton.classList.remove('visible'); renderCategories(); renderPersonalPanel(); renderList();
});
randomButton.addEventListener('click', async () => {
  const item = data[Math.floor(Math.random() * data.length)];
  await copyItem(item.text);
  const original = randomButton.textContent; randomButton.textContent = `已複製 ${item.text}`;
  window.setTimeout(() => { randomButton.textContent = original; }, 1200);
});
resetCategoryOrderButton.addEventListener('click', () => {
  categories = [...defaultCategories]; localStorage.removeItem('kaomoji-category-order'); saveCategoryOrder(); renderCategories();
});
const moods = ['可愛', '哭', '加油', '愛心', '晚安', '打招呼', '生氣'];
moodButton.addEventListener('click', () => {
  const mood = moods[Math.floor(Math.random() * moods.length)]; setSearch(mood);
  moodButton.textContent = `今天試試 ${mood}`; window.setTimeout(() => { moodButton.textContent = '心情探索'; }, 1300);
});
toolTabs.forEach(button => button.addEventListener('click', () => { personalView = button.dataset.personalView; renderPersonalPanel(); }));
themeToggle.addEventListener('click', () => {
  const dark = document.documentElement.dataset.theme !== 'dark'; document.documentElement.dataset.theme = dark ? 'dark' : '';
  localStorage.setItem('kaomoji-theme', dark ? 'dark' : 'light'); document.querySelector('meta[name="theme-color"]').content = dark ? '#171717' : '#fafafa';
});
document.querySelector('.dialog-close').addEventListener('click', () => detailsDialog.close());
detailCopy.addEventListener('click', async () => { if (detailItem) { await copyItem(detailItem.text); detailCopy.textContent = '已複製'; window.setTimeout(() => { detailCopy.textContent = '複製'; }, 900); } });
detailShare.addEventListener('click', async () => {
  if (!detailItem) return;
  const url = `${location.origin}${location.pathname}?q=${encodeURIComponent(detailItem.text)}`;
  try { if (navigator.share) await navigator.share({ title: '顏文字', text: detailItem.text, url }); else await navigator.clipboard.writeText(url); detailShare.textContent = '連結已準備好'; }
  catch { /* 使用者取消分享時不顯示錯誤 */ }
  window.setTimeout(() => { detailShare.textContent = '分享連結'; }, 1200);
});
const savedTheme = localStorage.getItem('kaomoji-theme');
if (savedTheme === 'dark' || (!savedTheme && matchMedia('(prefers-color-scheme: dark)').matches)) { document.documentElement.dataset.theme = 'dark'; document.querySelector('meta[name="theme-color"]').content = '#171717'; }
const sharedQuery = new URLSearchParams(location.search).get('q');
if (sharedQuery) setSearch(sharedQuery);
document.addEventListener('keydown', event => {
  const isTyping = ['INPUT', 'TEXTAREA'].includes(document.activeElement?.tagName);
  if (event.key === '/' && !isTyping) { event.preventDefault(); searchInput.focus(); }
  if (event.key === 'Escape' && isTyping && searchInput.value) { setSearch(''); }
  if (!isTyping && ['ArrowRight', 'ArrowLeft', 'ArrowDown', 'ArrowUp'].includes(event.key)) {
    const buttons = [...document.querySelectorAll('.kaomoji-copy')]; const current = buttons.indexOf(document.activeElement);
    const columns = innerWidth <= 640 ? 2 : innerWidth <= 900 ? 3 : 5;
    const delta = event.key === 'ArrowRight' ? 1 : event.key === 'ArrowLeft' ? -1 : event.key === 'ArrowDown' ? columns : -columns;
    const target = buttons[Math.max(0, Math.min(buttons.length - 1, (current < 0 ? 0 : current) + delta))];
    if (target) { event.preventDefault(); target.focus(); }
  }
  if (!isTyping && event.key === 'Enter' && document.activeElement?.classList.contains('kaomoji-copy')) document.activeElement.click();
});

renderCategories();
renderFilters();
renderPersonalPanel();
renderList();
if ('serviceWorker' in navigator) window.addEventListener('load', () => navigator.serviceWorker.register('./service-worker.js'));
